// 데일리드롭 웹사이트 빌더: 호(edition) HTML → public/ (최신호·보관함·용어사전·소개·구독·설정, 국가판별 /<prefix>/)
// 사용: node site/build.js <editions.json> [OUT]   editions.json = [{date:"2026-10-05", no:1, file:"editions/…html", region?:"US", translations?:{en:"…"}}, ...]
//   OUT 기본값 site/public (환경변수 DD_OUT 로도 지정). 나라 데이터는 site/countries.json, UI 문구는 site/i18n.json.
const fs = require('fs'), path = require('path');
const [, , spec, outArg] = process.argv;
// 예약 발행: publish_at(ISO, UTC)이 아직 안 된 호는 이번 빌드에서 뺀다(DD_NOW로 기준 시각 덮어쓰기). 공개 시각이 되면 사이트 Worker가 schedule.js가 만든 _sched 사본을 대신 내보낸다.
const NOW = Number(process.env.DD_NOW) || Date.now();
const editions = JSON.parse(fs.readFileSync(spec, 'utf8')).filter(e => !e.publish_at || Date.parse(e.publish_at) <= NOW).map(e => ({ ...e, file: path.resolve(path.dirname(spec), e.file) })).sort((a, b) => a.date.localeCompare(b.date));
const OUT = path.resolve(outArg || process.env.DD_OUT || path.join(__dirname, 'public')); fs.rmSync(OUT, { recursive: true, force: true }); fs.mkdirSync(OUT, { recursive: true });
const SITE = 'https://dailydrop.kr';
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
// 판 표기 전환일: 이 날짜부터 아침판(각국 현지 06:00 발행), 그 전 호(1~4호)는 현지시각 18:00판.
const MORNING_FROM = '2026-10-09';
const isAM = d => d >= MORNING_FROM;
const KO_ED = d => isAM(d) ? '아침판' : '현지시각 18:00판', JA_ED = d => isAM(d) ? '朝刊' : '現地時間18:00版';
const KO_DAY = ['일', '월', '화', '수', '목', '금', '토'];
const fmt = d => { const [y, m, dd] = d.split('-').map(Number); return `${y}년 ${m}월 ${dd}일 ${KO_DAY[new Date(Date.UTC(y, m - 1, dd)).getUTCDay()]}요일`; };

// ── 국가판·언어 데이터: countries.json(30개국, 순서 = 목록 순서) · i18n.json(UI 20개 언어, 빠진 키는 en)
const COUNTRIES = JSON.parse(fs.readFileSync(path.join(__dirname, 'countries.json'), 'utf8'));
const CBY = Object.fromEntries(COUNTRIES.map(c => [c.code, c]));
const I18N = JSON.parse(fs.readFileSync(path.join(__dirname, 'i18n.json'), 'utf8'));
const LANGS = ['en', 'ko', 'ja', ...Object.keys(I18N).filter(l => !['en', 'ko', 'ja'].includes(l))]; // 언어 메뉴 순서
const T = (l, k) => (I18N[l] && I18N[l][k] != null ? I18N[l][k] : I18N.en[k]);
// 회원(로그인·마이페이지·북마크·방문 비콘·관리자 리포트) UI: account-ui.js, API: src/account.js
const ACC = require('./account-ui.js');
for (const e of editions) if (!CBY[e.region || 'KR']) throw new Error(`editions.json: unknown region "${e.region}" (${e.date}); add it to countries.json`);
// 발행 중(live) = editions.json에 그 나라 호가 하나라도 있음. 아니면 '준비 중'(링크 없음), 페이지도 만들지 않는다.
const LIVE = new Set(['KR', ...editions.map(e => e.region || 'KR')]);
// 호수는 모든 국가판 공통, 한국판 기준(하루 한 호). 다른 판의 no가 어긋나면 빌드 중단.
(() => {
  const kr = editions.filter(e => (e.region || 'KR') === 'KR'); if (!kr.length) return;
  const krNo = new Map(kr.map(e => [e.date, e.no])); const d0 = kr[0].date, n0 = kr[0].no; const days = (a, b) => Math.round((Date.parse(a + 'T00:00:00Z') - Date.parse(b + 'T00:00:00Z')) / 864e5);
  for (const e of editions) { if ((e.region || 'KR') === 'KR') continue; const has = krNo.has(e.date); const want = has ? krNo.get(e.date) : n0 + days(e.date, d0); if (e.no !== want) throw new Error(`edition number mismatch: region ${e.region} date ${e.date}: expected No. ${want} (${has ? `KR edition of ${e.date}` : `KR sequence, No. ${n0} = ${d0}`}), got No. ${e.no}`); }
})();
// 번역본 자동 감지: 원본 <dir>/<date>.html 옆의 <date>.<lang>.html (lang = UI 언어 코드). editions.json의 translations가 우선. 미완성 파일(</script>로 안 끝남)은 경고 후 건너뜀.
for (const e of editions) {
  const dir = path.dirname(e.file), base = path.basename(e.file, '.html'), own = CBY[e.region || 'KR'].langs[0]; const tr = { ...(e.translations || {}) };
  for (const l of LANGS) { if (tr[l] || l === own) continue; const f = path.join(dir, `${base}.${l}.html`); if (!fs.existsSync(f)) continue; const body = fs.readFileSync(f, 'utf8').replace(/\s*<\/body>\s*<\/html>\s*$/i, '').trim(); if (!body.endsWith('</script>')) { console.warn(`translation skipped (incomplete): ${path.relative(process.cwd(), f)}`); continue; } tr[l] = path.relative(path.dirname(spec), f); }
  if (Object.keys(tr).length) e.translations = tr;
}

// ── 국가판: KR(루트) · 그 밖은 /<iso>/. 각 판은 '그 나라 국내 뉴스 + 글로벌 뉴스'. 제호는 공통(DailyDrop.), 날짜줄·메뉴·시세표 라벨만 현지어
const EN_DAY = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'], EN_MON = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const JA_DAY = ['日', '月', '火', '水', '木', '金', '土'];
const dayIdx = d => { const [y, m, dd] = d.split('-').map(Number); return new Date(Date.UTC(y, m - 1, dd)).getUTCDay(); };
// 날짜 표기: ko/en/ja는 손으로 정한 형식, 나머지는 Intl 'full'
const DATEFMT = { ko: fmt, en: d => { const [y, m, dd] = d.split('-').map(Number); return `${EN_DAY[dayIdx(d)].slice(0, 3)}., ${EN_MON[m - 1].slice(0, 3)}. ${dd}, ${y}`.toUpperCase(); }, ja: d => { const [y, m, dd] = d.split('-').map(Number); return `${y}年${m}月${dd}日（${JA_DAY[dayIdx(d)]}）`; } };
const dateIn = l => DATEFMT[l] || (DATEFMT[l] = d => { const [y, m, dd] = d.split('-').map(Number); return new Intl.DateTimeFormat(l, { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' }).format(Date.UTC(y, m - 1, dd)); });  // 날짜줄 한 줄 유지를 위해 요일·월은 약식(예: Mi., 7. Okt. 2026)
const edLabel = (l, n, d) => T(l, isAM(d) ? 'editionAM' : 'edition').replace('{n}', n);
// 나라 이름: i18n 고정 표기(ko/en/ja의 KR·US·JP) → 없으면 Intl.DisplayNames. 날짜줄용은 대소문자 있는 문자면 대문자(en 'KOREA'처럼)
const cname = (l, k, upper) => { const o = (I18N[l] && I18N[l].country || {})[k]; if (o) return o; let n; try { n = new Intl.DisplayNames([l], { type: 'region' }).of(k); } catch (err) { n = k; } return upper ? n.toLocaleUpperCase(l) : n; };
const COUNTRY = (l, k) => cname(l, k, true);
// 정렬 키: 일본어 한자 국명은 읽기(가나)로 50음순 정렬
const JA_READ = { KR: 'かんこく', US: 'べいこく', JP: 'にほん', TW: 'たいわん', CN: 'ちゅうごく' };
const SORTKEY = (l, k, name) => (l === 'ja' && JA_READ[k]) || name;
const EDNAME = (l, k) => (I18N[l] && I18N[l].ednames || {})[k] || T(l, 'edname').replace('{c}', cname(l, k, false));
const LANGCODE = l => (I18N[l] || {}).langcode || l.toUpperCase();
const LANGNAME = l => I18N[l] ? I18N[l].langname : l;
const tapeLabel = (l, k) => (k === 'gold' ? T(l, 'gold') : k);
// 번역판 시세표 라벨: 원본 판 언어로 적힌 라벨(나스닥·日経平均 등)을 보는 언어로. 표에 없는 언어는 en, en도 없으면 원래 라벨
const TAPE_L = { nasdaq: { ko: '나스닥', ja: 'ナスダック', en: 'Nasdaq' }, kospi: { ko: '코스피', en: 'KOSPI' }, kosdaq: { ko: '코스닥', en: 'KOSDAQ' }, usdkrw: { ko: '원/달러', ja: 'ドル/ウォン', en: 'USD/KRW' }, nikkei: { ko: '닛케이225', ja: '日経平均', en: 'Nikkei 225' }, usdjpy: { ko: '엔/달러', ja: 'ドル円', en: 'USD/JPY' }, dow: { ko: '다우', ja: 'ダウ', en: 'Dow' }, us10y: { ko: '미 10년물', ja: '米10年債', en: '10-yr' } };
const tapeLabelIn = (l, key, label) => key === 'gold' ? T(l, 'gold') : (TAPE_L[key] ? TAPE_L[key][l] || TAPE_L[key].en : label);
// 소개문(meta description) {c}: 언어별 국명 문법 — en 정관사, fr 전치사(au/aux), ko 조사(과/와), ja 판 표기(朝刊/夕刊)
const EN_THE = new Set(['US', 'GB', 'NL', 'PH', 'AE']);
const FR_IN = { CA: 'au Canada', JP: 'au Japon', BR: 'au Brésil', MX: 'au Mexique', VN: 'au Viêt Nam', PH: 'aux Philippines', US: 'aux États-Unis', GB: 'au Royaume-Uni', NL: 'aux Pays-Bas', AE: 'aux Émirats arabes unis', NG: 'au Nigeria' };
const DESC = (l, k, d) => { let n = cname(l, k, false); if (/[A-Z]/.test(n) && n === n.toUpperCase()) try { n = new Intl.DisplayNames([l], { type: 'region' }).of(k); } catch (err) { } let t = T(l, 'desc'); if (l === 'fr') t = t.replace('en {c}', FR_IN[k] || 'en {c}'); if (l === 'en' && EN_THE.has(k)) t = t.replace('{c}', 'the {c}'); if (l === 'ko') { const c = n.charCodeAt(n.length - 1) - 0xAC00; t = t.replace('{c}과', '{c}' + (c >= 0 && c < 11172 && c % 28 === 0 ? '와' : '과')); } if (l === 'ja' && d) t = t.replace('夕刊', isAM(d) ? '朝刊' : '夕刊'); return t.replace('{c}', n); };
// 번역판 제목: 보는 언어로(판 이름·호수·날짜)
const TTITLE = (l, k, n, d) => `DailyDrop ${EDNAME(l, k)} ${edLabel(l, n, d)} · ${dateIn(l)(d)}`;
// 손으로 다듬은 기존 3개 판(KR·US·JP). 나머지 나라는 mkRegion이 데이터로 만든다.
const LEGACY = {
  KR: { place: '서울', title: (n, d) => `데일리드롭 제${n}호 · ${fmt(d)} ${KO_ED(d)}`, desc: () => '국내외 전 분야 이슈를 매일 한 장에. 기사를 누르면 펼쳐지고 점선 단어를 누르면 뜻이 뜹니다.', tapeNote: '미국 지수·WTI는 직전 미국장 종가', soon: d => `첫 호는 ${fmt(d)} 아침 6시에 나옵니다.` },
  US: { place: 'NEW YORK', title: (n, d) => `DailyDrop U.S. No. ${n} · ${EN_MON[+d.slice(5, 7) - 1]} ${+d.slice(8, 10)}, ${d.slice(0, 4)}`, desc: () => 'The day in the United States and the world on one front page. Tap a story to unfold it; tap a dotted word for its meaning.', tapeNote: 'Indexes, WTI and gold: latest U.S. close', soon: d => `The first U.S. edition publishes at 6 a.m. on ${EN_MON[+d.slice(5, 7) - 1]} ${+d.slice(8, 10)}, ${d.slice(0, 4)}.` },
  JP: { place: '東京', title: (n, d) => `DailyDrop 日本版 第${n}号・${d.slice(0, 4)}年${+d.slice(5, 7)}月${+d.slice(8, 10)}日 ${JA_ED(d)}`, desc: d => `日本と世界の一日を新聞一面にまとめる${JA_ED(d)}。記事を押すと開き、点線の語を押すと意味が出ます。`, tapeNote: '米国指数・WTI・金は直近の米国市場終値', soon: d => `日本版 第1号は ${d.slice(0, 4)}年${+d.slice(5, 7)}月${+d.slice(8, 10)}日 午前6時に発行します。` },
};
const mkRegion = c => { const l = c.langs[0], D = dateIn(l); const R = { prefix: c.prefix, lang: l, place: c.city, date: D, edition: (n, d) => edLabel(l, n, d), latest: T(l, 'latest'), archive: T(l, 'archive'), glossary: T(l, 'glossary'), about: T(l, 'about'), subscribe: T(l, 'subscribe'), settings: T(l, 'settings'), inside: T(l, 'inside'), filler: T(l, 'filler'), tapeNote: T(l, 'tapeNote'), tape: c.tape.map(([k, m, kind]) => [tapeLabel(l, k), m, kind]), title: (n, d) => `DailyDrop ${EDNAME(l, c.code)} ${edLabel(l, n, d)} · ${D(d)}`, desc: d => DESC(l, c.code, d), soon: d => T(l, 'soon').replace('{date}', D(d)) }; return { ...R, ...(LEGACY[c.code] || {}) }; };
const REGIONS = Object.fromEntries(COUNTRIES.map(c => [c.code, mkRegion(c)]));
const REGION_PAGES = COUNTRIES.filter(c => c.code !== 'KR' && (LIVE.has(c.code) || c.phase === 0)).map(c => c.code); // /<prefix>/ 페이지를 만드는 판
fs.writeFileSync(path.join(OUT, 'live.json'), JSON.stringify(COUNTRIES.filter(c => LIVE.has(c.code)).map(c => ({ code: c.code, prefix: c.prefix }))));
// 날짜줄 국가판 전환: '▼ 대한민국' 을 누르면 발행 중인 국가판 목록 + 맨 끝 '전체 국가판 →'(설정 페이지의 30개국 카탈로그). 표기는 보는 언어 기준.
const EDPICK = (lang, region) => `<details class="dd-ed"><summary aria-label="${esc(T(lang, 'changeEdition'))}"><i aria-hidden="true">▼</i>${esc(COUNTRY(lang, region))}</summary><span class="dd-ed-menu">${COUNTRIES.filter(c => LIVE.has(c.code) || c.phase <= 1 || c.menu).sort((a, b) => new Intl.Collator(lang).compare(SORTKEY(lang, a.code, EDNAME(lang, a.code)), SORTKEY(lang, b.code, EDNAME(lang, b.code)))).map(c => c.code === region ? `<span aria-current="true" data-cc="${c.code}">${esc(EDNAME(lang, c.code))}</span>` : LIVE.has(c.code) ? `<a data-cc="${c.code}" href="/${c.prefix}?r=${c.code}">${esc(EDNAME(lang, c.code))}</a>` : `<span class="dd-ed-soon" data-cc="${c.code}" aria-disabled="true">${esc(EDNAME(lang, c.code))}<small>${esc(T(lang, 'soonShort'))}</small></span>`).join('')}<a class="dd-ed-all" href="/${REGIONS[region].prefix}settings/">${esc(T(lang, 'allEditions'))}</a></span></details>`;
// 날짜줄 오른쪽 호수 표기: 넓은 화면은 전체('제5호 · 현지시각 6:00판'), 좁은 화면은 짧게('제5호 · 6:00판'). 글자 크기는 그대로.
// 판 표기: 그 나라 판의 현지 발행 시각 + 시간대(번역판도 원래 나라 기준). 1~4호 18:00, 5호(10/9)부터 06:00 아침판.
const TZ_ABBR = { KR: 'KST', JP: 'JST', US: 'ET', CA: 'ET', IN: 'IST', AU: 'AET', TW: 'Taipei', SG: 'SGT', BR: 'BRT', MX: 'CST', AR: 'ART', ID: 'WIB', VN: 'ICT', TH: 'ICT', PH: 'PHT', TR: 'TRT', SA: 'AST', AE: 'GST', IL: 'Israel', ZA: 'SAST', NG: 'WAT' };
// 약어가 없는 시간대(도시 이름 표기)는 보는 언어로
const TZ_L = { TW: { 'zh-TW': '台灣時間', ja: '台北時間', ko: '타이베이 시간' } };
const TZ = (region, d, lang) => { if (TZ_L[region] && TZ_L[region][lang]) return TZ_L[region][lang]; if (TZ_ABBR[region]) return TZ_ABBR[region]; const c = COUNTRIES.find(x => x.code === region); try { return new Intl.DateTimeFormat('en-GB', { timeZone: c.tz, timeZoneName: 'short' }).formatToParts(new Date(d + 'T06:00:00Z')).find(p => p.type === 'timeZoneName').value; } catch (e) { return ''; } };
const EDTXT = (lang, region, n, d) => { const am = isAM(d), z = TZ(region, d, lang); const num = T(lang, 'editionShort').replace('{n}', n).split(/\s·\s|・/)[0];
  const time = lang === 'en' ? (am ? `6:00 a.m. ${z}` : `6:00 p.m. ${z}`) : `${am ? '06:00' : '18:00'} ${z}`;
  const timeShort = lang === 'en' ? (am ? `6 a.m. ${z}` : `6 p.m. ${z}`) : time;
  const word = am ? (T(lang, 'editionAM').split(/\s·\s|・/)[1] || '') : '';
  const sep = lang === 'ja' || lang === 'zh-TW' ? '・' : ' · ';
  const full = am ? `${num}${sep}${word}${lang === 'en' ? ', ' : ' '}${time}` : `${num}${sep}${time}`;
  return { full, num, right: timeShort }; };
const DL_LEFT = (year, lang, region, n, d) => `<small class="cpy">© ${year} DailyDrop</small><small class="eno">${EDTXT(lang, region, n, d).num}</small>`;
const EDLABEL = (lang, region, n, d) => { const t = EDTXT(lang, region, n, d); return `<small class="edf">${t.full}</small><small class="eds">${t.right}</small>`; };
const DATELINE_CSS = `<style>.dateline small{font-size:inherit;color:inherit;letter-spacing:inherit}.dateline .eno,.dateline .eds{display:none}@media(max-width:639px){.dateline{grid-template-columns:minmax(max-content,1fr) minmax(0,max-content) minmax(max-content,1fr)!important;column-gap:8px}.dateline>b{min-width:0;overflow:hidden;text-overflow:clip}.dateline>b:has(.dd-ed[open]),.dateline>b.dd-open{overflow:visible}.dateline>b .dd-ed{max-width:100%}.dateline>*{white-space:nowrap}.dateline>span:first-child{text-align:left}.dateline>b{text-align:center!important}.dateline>span:last-child{text-align:right}.dateline .cpy,.dateline .edf{display:none}.dateline .eno,.dateline .eds{display:inline}}</style>`;
const LOCFIRST = `<script>(function(){try{var m=document.cookie.match(/(?:^|;\\s*)dd_cc=([A-Z]{2})/);if(!m)return;var cc=m[1];document.querySelectorAll('.dd-ed-menu').forEach(function(u){var el=u.querySelector('[data-cc="'+cc+'"]');if(el)u.insertBefore(el,u.firstChild);});var row=document.querySelector('.crow[data-cc="'+cc+'"]'),g=document.querySelector('.cgrp');if(row&&g){var sec=g.cloneNode(false);sec.removeAttribute('data-group');sec.className='cgrp here';sec.appendChild(row);g.parentNode.insertBefore(sec,g);}}catch(e){}})();</script>`;
