const PAPERBG = `<style>html{background:#ece4d8}body{min-height:100vh;min-height:100dvh}@media(prefers-color-scheme:dark){html:not([data-theme="light"]){background:#14130f}}html[data-theme="dark"]{background:#14130f}</style><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><script>(function(){var done={};function pf(u){if(!u||u.indexOf("/")!==0)return;u=u.split("?")[0].split("#")[0];if(done[u])return;done[u]=1;var l=document.createElement("link");l.rel="prefetch";l.href=u;document.head.appendChild(l)}document.addEventListener("toggle",function(e){var d=e.target;if(d&&d.open&&d.classList&&(d.classList.contains("dd-ed")||d.classList.contains("dd-lang")))d.querySelectorAll("a[href]").forEach(function(a){pf(a.getAttribute("href"))})},true);document.addEventListener("pointerdown",function(e){var a=e.target.closest&&e.target.closest(".dd-ed a[href],.dd-lang a[href],.dd-nav a[href]");if(a)pf(a.getAttribute("href"))},true)})();</script>`;
const NOBLOCK = h => String(h).replace(/<link rel="stylesheet" href="(https:\/\/fonts\.googleapis\.com\/[^"]+)">/g, (m, u) => `<link rel="preload" as="style" href="${u}"><link rel="stylesheet" href="${u}" media="print" onload="this.media='all'"><noscript><link rel="stylesheet" href="${u}"></noscript>`).replace(/<meta charset="utf-8">/i, m => m + PAPERBG);
{ const _w = fs.writeFileSync; fs.writeFileSync = (f, d, ...r) => _w(f, typeof d === 'string' && /\.html$/.test(String(f)) && !d.includes('rel="preconnect" href="https://fonts.googleapis.com"') ? NOBLOCK(d) : d, ...r); }
const HEAD = (title, desc, pathname = '/', lang = 'ko') => `<!doctype html><html lang="${lang}"${T(lang, 'dir') === 'rtl' ? ' dir="rtl"' : ''}><head><meta charset="utf-8">${TEXTSCALE}<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>${esc(title)}</title><meta name="description" content="${esc(desc)}"><link rel="canonical" href="${SITE}${pathname}"><meta property="og:url" content="${SITE}${pathname}"><meta property="og:type" content="article"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(desc)}"><meta property="og:site_name" content="${lang === 'ko' ? '데일리드롭' : 'DailyDrop'}"><meta property="og:image" content="${SITE}/og.png"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/brand/favicon-32.png" sizes="32x32" type="image/png"><link rel="icon" href="/brand/favicon-16.png" sizes="16x16" type="image/png"><link rel="apple-touch-icon" href="/brand/apple-touch-icon.png"><meta name="apple-mobile-web-app-title" content="DailyDrop"><meta name="application-name" content="DailyDrop"><link rel="manifest" href="/manifest.webmanifest"><meta name="theme-color" content="#ece4d8">${NAVCSS}${ACC.NAV_CSS}${XFONTS(lang)}${T(lang, 'dir') === 'rtl' ? RTLCSS : ''}</head><body${lang !== 'ko' ? ` data-filler="${esc(T(lang, 'filler'))}"` : ''}>`;
// 한·영·일 외 문자권 페이지만 그 문자의 Noto 글꼴을 더 불러온다(ko/en/ja 페이지는 그대로)
const XFONT = { hi: ['Noto Serif Devanagari', 'Noto Sans Devanagari'], th: ['Noto Serif Thai', 'Noto Sans Thai'], ar: ['Noto Naskh Arabic', 'Noto Sans Arabic'], he: ['Noto Serif Hebrew', 'Noto Sans Hebrew'], 'zh-TW': ['Noto Serif TC', 'Noto Sans TC'] };
const XFONTS = l => { const f = XFONT[l]; return f ? `<link rel="stylesheet" href="https://fonts.googleapis.com/css2?${f.map(n => `family=${n.replace(/ /g, '+')}:wght@400;700`).join('&')}&display=swap"><style>html:root{--serif:"Noto Serif","${f[0]}",Georgia,serif;--sans:"Noto Sans","${f[1]}",sans-serif}html body,.dd-nav{font-family:var(--serif)}</style>` : ''; };
// 아랍어·히브리어: 문서는 rtl, 제호는 ltr 유지, 풀다운은 반대쪽에 붙인다
const RTLCSS = `<style>[dir=rtl] .mast,[dir=rtl] h1[lang=en],[dir=rtl] .dd-logo{direction:ltr}[dir=rtl] .dd-lang-menu{right:auto;left:0}[dir=rtl] .dd-ed-menu{left:auto;right:0}[dir=rtl] .dd-ed-menu,[dir=rtl] .dd-ed-menu a,[dir=rtl] .dd-ed-menu span{text-align:right!important;text-align-last:right!important}[dir=rtl] .dd-ed summary i{margin-right:0;margin-left:.35em}</style>`;
const BASECSS = `<style>:root{--paper:#ece4d8;--ink:#1b1a17;--ink-2:#3d3a33;--mute:#7b7569;--rule:#b9b1a0;--red:#8d2f22}@media(prefers-color-scheme:dark){:root:not([data-theme="light"]){--paper:#14130f;--ink:#ebe4d6;--ink-2:#c7bfaf;--mute:#8d8576;--rule:#4a443a;--red:#e2765f;color-scheme:dark}}:root[data-theme="dark"]{--paper:#14130f;--ink:#ebe4d6;--ink-2:#c7bfaf;--mute:#8d8576;--rule:#4a443a;--red:#e2765f;color-scheme:dark}:root[data-theme="light"]{color-scheme:light}body{margin:0;background:var(--paper) url(data:image/png;base64,);background-size:320px 320px;color:var(--ink);font-family:"Noto Serif KR",Georgia,serif;line-height:1.65}main{max-width:760px;margin:0 auto;padding:28px 16px 60px}h1{font-size:30px;font-weight:900;letter-spacing:-.03em;line-height:1.25;margin:0 0 6px}h2{font-size:18px;margin:34px 0 10px;border-bottom:1px solid var(--rule);padding-bottom:6px}p{margin:0 0 14px}.mute{color:var(--mute);font-family:"Noto Sans KR",sans-serif;font-size:13px}.card{display:block;color:inherit;text-decoration:none;border:1px solid var(--rule);padding:16px 18px;margin:14px 0;background:rgba(0,0,0,.02)}.card b{font-size:19px;display:block;margin-bottom:4px}.card:hover{border-color:var(--red)}.btn{display:inline-block;background:var(--red);color:#fff;text-decoration:none;padding:12px 20px;font-family:"Noto Sans KR",sans-serif;font-weight:700;letter-spacing:.04em;margin-top:8px}.term{border-bottom:1px solid var(--rule);padding:14px 0}.term h3{margin:0 0 4px;font-size:17px}.term .f{color:var(--red);font-family:"Noto Sans KR",sans-serif;font-size:11.5px;letter-spacing:.14em;margin-left:8px}.term .w{color:var(--ink-2);font-size:14.5px;margin-top:6px}.term .src{color:var(--mute);font-family:"Noto Sans KR",sans-serif;font-size:12px;margin-top:4px}input[type=search]{width:100%;box-sizing:border-box;font:16px "Noto Sans KR",sans-serif;padding:10px 12px;border:1px solid var(--rule);background:transparent;color:inherit;margin:8px 0 10px}</style>`;

// 제호 아래 시세표 한 줄: S&P 500 · 나스닥 · 코스피 · 코스닥 · 원/달러 (markets.json, 호별)
const MARKETS = JSON.parse(fs.readFileSync(path.join(__dirname, 'markets.json'), 'utf8'));
const fmtNum = (v, d) => v.toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d });
// 시세표는 항상 한 줄(사장님 10/9): 좁은 화면에서 칸을 넘으면 줄바꿈 대신 시세표 글자만 조금씩 줄인다(최소 72%). 실시간 시세로 값이 바뀌면 다시 맞춘다
const TAPEFIT = "<script>(function(){var t=document.currentScript.previousElementSibling;if(!t)return;var busy=0;function bad(){var qs=t.querySelectorAll('.q');for(var i=0;i<qs.length;i++){var q=qs[i];if(q.scrollWidth>q.clientWidth+.5)return true}return false}function fit(){if(busy)return;busy=1;var z=1;t.style.setProperty('--tz',1);while(bad()&&z>.72){z=Math.round((z-.03)*100)/100;t.style.setProperty('--tz',z)}setTimeout(function(){busy=0},0)}fit();addEventListener('resize',fit);addEventListener('load',fit);if(document.fonts&&document.fonts.ready)document.fonts.ready.then(fit);var tm;new MutationObserver(function(){if(busy)return;clearTimeout(tm);tm=setTimeout(fit,50)}).observe(t,{subtree:true,childList:true,characterData:true})})()</script>";
const TAPE = (date, region = 'KR', lang = null) => {
  const R = REGIONS[region]; const tl = lang && lang !== R.lang ? lang : null; const m = (MARKETS[region] && MARKETS[region][date]) || (region === 'KR' ? MARKETS[date] : null); if (!m) return '';
  const cell = (label, q, kind, key) => {
    if (!q) return `<span class="q na" data-k="${key}" data-kind="${kind || ''}"><b>${label}</b><em>—</em><i><u></u><span></span></i><small></small></span>`;
    const d = kind === 'rate' ? 4 : kind === 'fx' ? 1 : kind === 'fxjpy' ? 2 : kind === 'pct' ? 2 : 2; const up = q.chg > 0, down = q.chg < 0; const unit = kind === 'usd' ? '$' : '';
    const tri = down ? '▼' : up ? '▲' : '－';
    const chgTxt = q.chg == null ? '' : kind === 'fx' ? Math.abs(q.chg).toFixed(1) + ({ ko: '원', ja: 'ウォン' }[tl || R.lang] || ' KRW') : kind === 'fxjpy' ? Math.abs(q.chg).toFixed(2) + ({ ja: '円', ko: '엔' }[tl || R.lang] || ' JPY') : kind === 'pct' ? Math.round(Math.abs(q.chg) * 100) + 'bp' : Math.abs(q.chg).toFixed(2) + '%';
    const val = kind === 'pct' ? fmtNum(q.v, 2) + '%' : unit + fmtNum(q.v, d);
    return `<span class="q${down ? ' dn' : up ? ' upp' : ''}" data-k="${key}" data-kind="${kind || ''}"><b>${label}</b><em>${val}</em><i><u>${tri}</u><span>${chgTxt}</span></i><small>${q.asof || ''}</small></span>`;
  };
  return `<div class="tape" aria-label="markets" data-note="${esc(tl ? T(tl, 'tapeNote') : R.tapeNote)}">${R.tape.map(([label, key, kind]) => cell(esc(tl ? tapeLabelIn(tl, key, label) : label), m[key], kind, key)).join('')}</div>` + TAPEFIT;
};

// 빈칸 메우기 풀(pool.json, 호별 여분 단신). 페이지에 숨겨 두고 balance.js가 짧은 열 바닥에 끼워 넣는다.
const POOL = fs.existsSync(path.join(__dirname, 'pool.json')) ? JSON.parse(fs.readFileSync(path.join(__dirname, 'pool.json'), 'utf8')) : {};
const POOLHTML = (date, region = 'KR') => { const items = POOL[`${region}:${date}`] || (region === 'KR' ? POOL[date] : []) || []; if (!items.length) return ''; return `<ul class="pool" hidden>${items.map(x => typeof x === 'string' ? { t: x } : x).filter(x => x && x.t).map(x => `<li><b>${esc(x.t)}</b>${x.s ? `<span>${esc(x.s)}</span>` : ''}</li>`).join('')}</ul>`; };
// 조판 균형: 데스크톱(≥860px)에서 같은 줄(.grid/.strip)의 열 높이를 재서 짧은 열 바닥에 풀 단신을 끼워 넣고, 그래도 남는 차이는 열을 늘려 바닥을 맞춘다. 창 크기가 바뀌면 다시.
// 줄마다 양끝 맞춤(신문식): 브라우저 기본 양끝 맞춤은 남는 폭을 띄어쓰기에만 몰아 넣어 단어 사이가 벌어진다.
// 왼쪽 맞춤으로 줄바꿈 위치를 잰 뒤, 줄마다 남는 폭을 그 줄 모든 글자 사이에 고르게(글자당 1px 안팎) 나눠 넣는다. 마지막 줄은 그대로.
const JUSTIFY = `<script>(function(){var SEL='.body p,.one p,.deck,.word p,.it em,.rumor div';var lastW=0;var LAT=!/^(ko|ja|zh)/.test(document.documentElement.lang||'');
function unwrap(p){var wbs=p.querySelectorAll('wbr.jl');for(var i=0;i<wbs.length;i++)wbs[i].remove();var s=p.querySelectorAll('span.jl');for(var i=0;i<s.length;i++){var x=s[i];x.parentNode.replaceChild(document.createTextNode(x.textContent),x);}p.normalize();}
function run(){var ps=document.querySelectorAll(SEL);for(var k=0;k<ps.length;k++){try{one(ps[k]);}catch(e){}}}
function one(p){unwrap(p);p.style.removeProperty('text-align');if(!p.offsetWidth)return;var cs=getComputedStyle(p);if(cs.textAlign!=='justify')return;
 p.style.setProperty('text-align','left','important');var pr=p.getBoundingClientRect();var right=pr.right-parseFloat(cs.paddingRight||0);
 var mc=p.parentElement,cn=1,cg=0,cl=0,cw=0;while(mc&&mc!==document.body){var mcs=getComputedStyle(mc);cn=parseInt(mcs.columnCount)||1;if(cn>1){cg=parseFloat(mcs.columnGap)||0;var mr=mc.getBoundingClientRect();cl=mr.left+parseFloat(mcs.paddingLeft||0);cw=(mr.width-parseFloat(mcs.paddingLeft||0)-parseFloat(mcs.paddingRight||0)-cg*(cn-1))/cn;break;}mc=mc.parentElement;}
 var base=parseFloat(cs.letterSpacing)||0;var fs=parseFloat(cs.fontSize)||14;var lh=parseFloat(cs.lineHeight)||fs*1.5;
 var w=document.createTreeWalker(p,NodeFilter.SHOW_TEXT,{acceptNode:function(n){return n.parentElement&&n.parentElement.closest('ruby,rt,rp')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}}),t,lines=[],cur=null,rg=document.createRange();
 while((t=w.nextNode())){for(var i=0;i<t.data.length;i++){rg.setStart(t,i);rg.setEnd(t,i+1);var r=rg.getClientRects()[0];if(!r||!r.width)continue;
  if(!cur||Math.abs(r.top-cur.top)>lh*0.5){cur={top:r.top,segs:[],n:0,sp:0,end:0,right:cn>1?cl+Math.min(cn-1,Math.max(0,Math.floor((r.left-cl+1)/(cw+cg))))*(cw+cg)+cw:right};lines.push(cur);}
  var sg=cur.segs[cur.segs.length-1];if(sg&&sg.t===t&&sg.b===i)sg.b=i+1;else cur.segs.push({t:t,a:i,b:i+1});
  if(/\\s/.test(t.data[i]))cur.sp++;else{cur.n++;cur.end=r.right;}}}
 var plan=[];for(var j=0;j<lines.length;j++){var L=lines[j];var slack=L.right-L.end-1.5;var ls=0;
  if(j<lines.length-1&&slack>0.2&&L.n>=4){ls=slack/(L.n+L.sp);if(LAT)ls=Math.min(ls,fs*0.04);else if(ls>fs*0.25)ls=0;}plan.push({L:L,ls:ls});}
 for(var q=plan.length-1;q>=0;q--){var L=plan[q].L,v=(base+plan[q].ls).toFixed(3)+'px';for(var m=L.segs.length-1;m>=0;m--){var g=L.segs[m];var tn=g.t;
  if(g.b<tn.data.length)tn.splitText(g.b);var mid=g.a>0?tn.splitText(g.a):tn;var sp=document.createElement('span');sp.className='jl';sp.style.letterSpacing=v;mid.parentNode.replaceChild(sp,mid);sp.appendChild(mid);
  if(m===L.segs.length-1&&q<plan.length-1){var wb=document.createElement('wbr');wb.className='jl';sp.parentNode.insertBefore(wb,sp.nextSibling);}}}
 var js=p.querySelectorAll('span.jl');for(var z=0;z<js.length;z++){var x=js[z];for(var tr=0;tr<4&&x.getClientRects().length>1;tr++){var cur2=parseFloat(x.style.letterSpacing)-base;x.style.letterSpacing=(tr<3?(base+cur2/2).toFixed(3)+'px':'');}}
 p.style.removeProperty('text-align');}
var tm;function later(){clearTimeout(tm);tm=setTimeout(function(){if(window.innerWidth!==lastW){lastW=window.innerWidth;run();}},150);}
function go(){lastW=window.innerWidth;run();}
if(document.readyState==='complete')go();else window.addEventListener('load',go);
if(document.fonts){if(document.fonts.ready)document.fonts.ready.then(function(){setTimeout(go,50);});if(document.fonts.addEventListener)document.fonts.addEventListener('loadingdone',function(){setTimeout(go,50);});}setTimeout(go,1500);
window.addEventListener('resize',later);})();<\/script>`;
const BALANCE = `<script>(function(){var mq=window.matchMedia('(min-width:860px)');var pool=document.querySelector('.pool');var items=pool?Array.prototype.slice.call(pool.children):[];
function reset(){document.querySelectorAll('.filler').forEach(function(f){f.remove();});document.querySelectorAll('.col').forEach(function(c){c.style.minHeight='';});}
function rows(){return Array.prototype.slice.call(document.querySelectorAll('main.grid, .strip'));}
function cols(row){return Array.prototype.slice.call(row.children).filter(function(c){return c.classList.contains('col')&&c.offsetParent!==null;});}
function balance(){reset();if(!mq.matches)return;var used=0;rows().forEach(function(row){var cs=cols(row);if(cs.length<2)return;row.style.alignItems='start';var tops={};cs.forEach(function(c){var t=c.offsetTop;(tops[t]=tops[t]||[]).push(c);});Object.keys(tops).forEach(function(t){var line=tops[t];if(line.length<2)return;var max=Math.max.apply(null,line.map(function(c){return c.offsetHeight;}));line.forEach(function(c){var gap=max-c.offsetHeight;if(gap<48||used>=items.length)return;var box=document.createElement('div');box.className='fill filler';var h=document.createElement('h5');h.textContent=(document.body.getAttribute('data-filler')||'단신');box.appendChild(h);var ul=document.createElement('ul');ul.className='briefs';box.appendChild(ul);c.appendChild(box);while(used<items.length){var li=items[used].cloneNode(true);ul.appendChild(li);if(c.offsetHeight>max){ul.removeChild(li);break;}used++;}if(!ul.children.length)box.remove();});var max2=Math.max.apply(null,line.map(function(c){return c.offsetHeight;}));line.forEach(function(c){c.style.minHeight=max2+'px';});});row.style.alignItems='';});}
var t;function run(){clearTimeout(t);t=setTimeout(balance,60);}
if(document.readyState==='complete')run();else window.addEventListener('load',run);window.addEventListener('resize',run);if(document.fonts&&document.fonts.ready)document.fonts.ready.then(run);})();</script>`;

// B안: 1면 하단 '안에서' 색인 띠 — 이 호의 기사 제목(h2/h3.hl)과 분류를 모아 콜로폰 위에 둔다. 가변 공간 흡수용 고정 요소
const INSIDE = (html, label = '안에서') => { const re = /<div class="kick">([^<]*)<span>[\s\S]*?<\/span><\/div>\s*<h[23] class="hl">([\s\S]*?)<\/h[23]>/g; const out = []; let m; while ((m = re.exec(html))) { out.push(`<span>${m[2].replace(/<br\s*\/?>/g, ' ').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim()}<i>${m[1].trim()}</i></span>`); } return out.length ? `<div class="inside" aria-label="${label}"><b>${label}</b>${out.join('')}</div>` : ''; };
const NYTCSS = '<style id="nyt">' + fs.readFileSync(path.join(__dirname, 'nyt.css'), 'utf8') + '</style>';
const FONTS = `<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Noto+Serif+KR:wght@300;400;600;700;900&family=Noto+Sans+KR:wght@400;500;700&display=swap">`;

// ── 호 페이지: 원본 HTML을 그대로 쓰되 문서 뼈대 + 상단 nav
// ── 원문 링크·인플루언서 발언(site/extras/<prefix><date>.json): { src: { <data-id>: [{n, u, alt?:[번역 표기…]}] }, infl: [{who, where, date, u, t:{<lang>: 발언 요지}}] }
// src: 팝업 '출처' 줄에서 매체 이름(n·alt)이 보이면 그 글자를 원문 링크로, 안 보이면 줄 끝에 '원문' 링크 칩으로 붙인다(번역본도 data-id가 같으니 한 파일로 모든 언어).
// infl: 판 하단(콜로폰 앞)에 작은 '인플루언서 발언' 상자 — 발언은 사실 확인 전 원문 요지, 언어별 t[l] 없으면 en → 판 언어 순으로 대체.
const XL = { ko: ['인플루언서 발언', '원문', '발언은 사실 확인 전 원문 요지입니다.'], en: ['Influencer watch', 'Source', 'Statements as posted, not fact-checked.'], ja: ['インフルエンサー発言', '原文', '発言は事実確認前の要旨です。'], 'zh-TW': ['意見領袖發言', '原文', '發言為原文要旨，尚未查證。'], de: ['Stimmen im Netz', 'Quelle', 'Aussagen wie gepostet, nicht geprüft.'], fr: ['Ils ont dit', 'Source', 'Propos tels que publiés, non vérifiés.'], pt: ['Disseram nas redes', 'Fonte', 'Declarações como publicadas, sem checagem.'], es: ['Lo dijeron en redes', 'Fuente', 'Declaraciones tal como se publicaron, sin verificar.'], it: ['Detto in rete', 'Fonte', 'Dichiarazioni come pubblicate, non verificate.'], nl: ['Gezegd online', 'Bron', 'Uitspraken zoals geplaatst, niet gecontroleerd.'], hi: ['प्रभावशाली आवाज़ें', 'स्रोत', 'बयान जैसे पोस्ट किए गए, सत्यापित नहीं।'], id: ['Kata para tokoh', 'Sumber', 'Pernyataan sesuai unggahan, belum diverifikasi.'] };
const xl = l => XL[l] || XL[String(l).split('-')[0]] || XL.en;
